import math


def ranked_root_gaps(values):
    triples = [(a, b, math.sqrt(abs(a - b))) for a, b in zip(values, values[1:])]
    return sorted(triples, key=lambda t: -t[2])

import re


def rotate_word_interiors(text, shift):
    def repl(match):
        word = match.group(0)
        if len(word) <= 3:
            return word
        middle = word[1:-1]
        k = shift % len(middle)
        return word[0] + middle[k:] + middle[:k] + word[-1]

    return re.sub(r"\w+", repl, text)

from itertools import cycle


def build_color_pattern(n_colors, colors, picks):
    if n_colors <= 0:
        return []
    if not colors:
        raise ValueError("colors must not be empty")
    needed = n_colors // 2
    if len(picks) < needed:
        raise ValueError("not enough picks")
    color_cycle = cycle(colors)
    pick_iter = iter(picks)
    result = []
    for i in range(n_colors):
        if i % 2 == 0:
            result.append(next(color_cycle))
        else:
            p = next(pick_iter)
            if not (0 <= p < len(colors)):
                raise ValueError("pick index out of range")
            result.append(colors[p])
    return result

import json

def common_record_keys(json_text):
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError):
        return None
    if not isinstance(data, list) or not all(isinstance(item, dict) for item in data):
        return None
    if not data:
        return []
    common = set(data[0])
    for item in data[1:]:
        common &= item.keys()
    return sorted(common)

import ipaddress

def port_status_map(ip_range, port, open_services):
    net = ipaddress.IPv4Network(ip_range)
    open_hosts = {ipaddress.IPv4Address(ip) for ip, ports in open_services.items() if port in ports}
    return {str(addr): addr in open_hosts for addr in net}

from datetime import datetime, timedelta

WEATHER_CONDITIONS = {'Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'}


def weather_log_csv(start, conditions):
    fmt = '%Y-%m-%d %H:%M'
    t0 = datetime.strptime(start, fmt)
    lines = ['Time,Condition']
    for i, cond in enumerate(conditions):
        if cond not in WEATHER_CONDITIONS:
            raise ValueError('unknown weather condition: %r' % (cond,))
        lines.append('%s,%s' % ((t0 + timedelta(hours=i)).strftime(fmt), cond))
    return '\n'.join(lines) + '\n'

import json
from datetime import datetime


def stamp_last_updated(json_text, timestamp):
    data = json.loads(json_text)
    if not isinstance(data, dict):
        raise ValueError("top-level JSON value must be an object")
    stamp = datetime(*timestamp).isoformat(sep=' ', timespec='microseconds')
    data['last_updated'] = stamp
    return json.dumps(data, indent=4, ensure_ascii=False)

import csv
import io

def find_first_matching_rows(files, target_value, column):
    if column < 0:
        raise ValueError("column must be non-negative")
    result = {}
    for name, text in files.items():
        if not name.endswith('.csv'):
            continue
        reader = csv.reader(io.StringIO(text, newline=''))
        for i, row in enumerate(reader):
            if len(row) > column and row[column] == target_value:
                result[name] = i
                break
    return result

import csv
import io


def summarize_timesheet(csv_text, id_prefix):
    reader = csv.DictReader(io.StringIO(csv_text))
    fields = reader.fieldnames or []
    if 'employee_id' not in fields or 'hours' not in fields:
        raise ValueError('CSV header must contain employee_id and hours columns')
    counts = {}
    totals = {}
    for row in reader:
        eid = row.get('employee_id')
        if eid is None or not eid.startswith(id_prefix):
            continue
        counts[eid] = counts.get(eid, 0) + 1
        totals[eid] = totals.get(eid, 0.0) + float(row['hours'])
    return {eid: (counts[eid], totals[eid]) for eid in counts}

import posixpath
import re


def plan_archive_extraction(target_dir, member_names):
    if not target_dir:
        raise ValueError("target_dir must be non-empty")
    base = target_dir.rstrip('/')
    result = []
    for name in member_names:
        if name.endswith('/') or name.endswith('\\'):
            continue
        path = name.replace('\\', '/')
        if path.startswith('/') or re.match(r'^[A-Za-z]:', path):
            raise ValueError("absolute member path: %r" % name)
        norm = posixpath.normpath(path)
        if norm in ('.', '..') or norm.startswith('../'):
            raise ValueError("member escapes target directory: %r" % name)
        result.append((name, base + '/' + norm))
    return result
